() => {
  const card = document.getElementById('card').getBoundingClientRect();
  const out = [];
  document.querySelectorAll('.inner *').forEach(el => {
    const r = el.getBoundingClientRect();
    if (r.width === 0) return;
    if (r.left < card.left - 0.5 || r.right > card.right + 0.5 || r.top < card.top - 0.5 || r.bottom > card.bottom + 0.5) {
      out.push('OVERFLOW ' + el.className + ' ' + JSON.stringify([r.left, r.top, r.right, r.bottom]));
    }
    if (el.scrollWidth > el.clientWidth + 1 && getComputedStyle(el).overflow !== 'hidden') {
      out.push('SCROLLW ' + el.className + ' ' + el.scrollWidth + '>' + el.clientWidth);
    }
  });
  const n = document.querySelector('.col-right .name').getBoundingClientRect();
  const cr = document.querySelector('.col-right').getBoundingClientRect();
  out.push('name w=' + n.width.toFixed(1) + ' col w=' + cr.width);
  return out.join('\n') || 'OK';
}

