async () => {
  const load = src => new Promise(res => { const i = new Image(); i.onload = () => res(src + ': ' + i.naturalWidth + 'x' + i.naturalHeight); i.onerror = () => res(src + ': ERROR'); i.src = src + '?t=' + Date.now(); });
  return (await Promise.all(['square.png','landscape.png','story.png'].map(load))).join('\n');
}
